/**
 * DOMPurify Browser Lite - Sanitizador de HTML seguro para Su Voz a Diario
 */
(function(global) {
  'use strict';
  
  function sanitize(html, config) {
    if (!html || typeof html !== 'string') return '';
    
    const allowedTags = (config && Array.isArray(config.ALLOWED_TAGS))
      ? config.ALLOWED_TAGS.map(t => t.toLowerCase())
      : ['b', 'i', 'u', 'blockquote', 'span', 'ul', 'li', 'p', 'br'];
      
    const allowedAttr = (config && Array.isArray(config.ALLOWED_ATTR))
      ? config.ALLOWED_ATTR.map(a => a.toLowerCase())
      : ['class', 'data-verse', 'data-format'];

    try {
      const parser = new DOMParser();
      const doc = parser.parseFromString(html, 'text/html');
      
      function cleanNode(node) {
        const children = Array.from(node.childNodes);
        for (const child of children) {
          if (child.nodeType === 1) { // Element node
            const tagName = child.tagName.toLowerCase();
            if (!allowedTags.includes(tagName)) {
              // Si no está permitido el tag, movemos sus hijos al padre y eliminamos la etiqueta
              while (child.firstChild) {
                node.insertBefore(child.firstChild, child);
              }
              node.removeChild(child);
            } else {
              // Limpiar atributos no permitidos o peligrosos
              const attrs = Array.from(child.attributes);
              for (const attr of attrs) {
                const attrName = attr.name.toLowerCase();
                const attrValue = attr.value.toLowerCase();
                if (!allowedAttr.includes(attrName) || attrName.startsWith('on') || attrValue.includes('javascript:')) {
                  child.removeAttribute(attr.name);
                }
              }
              cleanNode(child);
            }
          } else if (child.nodeType === 8 || child.nodeName === 'SCRIPT' || child.nodeName === 'STYLE') { // Comment or script
            node.removeChild(child);
          }
        }
      }
      
      cleanNode(doc.body);
      return doc.body.innerHTML;
    } catch (e) {
      console.warn('[DOMPurify] Fallback sanitization applied:', e);
      return html.replace(/<[^>]*>/g, '');
    }
  }

  global.DOMPurify = { sanitize: sanitize };
})(typeof window !== 'undefined' ? window : this);
